import{c as n,Q as s,j as e,m as t}from"./chunks/framework.DOi4mjdC.js";const l="/assets/allreduce.DTwgBFNx.png",p="/assets/AllReduce%E4%B8%89%E8%BD%AE%E5%88%87%E5%88%86%E9%80%9A%E4%BF%A1%E7%A4%BA%E4%BE%8B.EXeqqoBC.png",c="/assets/250902140829537_gai.ClPXJJrA.png",i="/assets/%E5%90%84%E5%8D%A1%E6%95%B0%E6%8D%AE%E5%88%87%E5%88%86%E7%A4%BA%E6%84%8F%E5%9B%BE.C0wXDAfE.png",d="/assets/4%E5%8D%A1AllReduce%E7%A4%BA%E6%84%8F%E5%9B%BE.BlWk0Zyj.png",f=JSON.parse('{"title":"AllReduce","description":"","frontmatter":{},"headers":[{"level":1,"title":"AllReduce","slug":"allreduce"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/AllReduce.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/AllReduce.md"}'),r={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/AllReduce.md"};function u(o,a,A,_,h,C){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="allreduce" tabindex="-1">AllReduce <a class="header-anchor" href="#allreduce" aria-label="Permalink to &quot;AllReduce&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>集合通信算子AllReduce的任务下发接口，返回该任务的标识handleId给用户。AllReduce功能为：将通信域内所有节点的同名张量进行reduce操作后，再把结果发送到所有节点的输出buffer。</p><p><img src="'+l+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool commit = false&gt;</span></span>
<span class="line"><span>__aicore__ inline HcclHandle AllReduce(GM_ADDR sendBuf, GM_ADDR recvBuf, uint64_t count, HcclDataType dataType, HcclReduceOp op, uint8_t repeat = 1)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>commit</td><td>输入</td><td>bool类型。参数取值如下： true：在调用Prepare接口时，Commit同步通知服务端可以执行该通信任务。false：在调用Prepare接口时，不通知服务端执行该通信任务。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>sendBuf</td><td>输入</td><td>源数据buffer地址。</td></tr><tr><td>recvBuf</td><td>输出</td><td>目的数据buffer地址，集合通信结果输出到此buffer中。</td></tr><tr><td>count</td><td>输入</td><td>参与AllReduce操作的数据个数，比如只有一个int32数据参与，则count=1。</td></tr><tr><td>dataType</td><td>输入</td><td>AllReduce操作的数据类型，目前支持float、half（即float16）、int8_t、int16_t、int32_t、bfloat16_t数据类型，即支持取值为HCCL_DATA_TYPE_FP32、HCCL_DATA_TYPE_FP16、HCCL_DATA_TYPE_INT8、HCCL_DATA_TYPE_INT16、HCCL_DATA_TYPE_INT32、HCCL_DATA_TYPE_BFP16。HcclDataType数据类型的介绍请参考表1。</td></tr><tr><td>op</td><td>输入</td><td>Reduce的操作类型，目前支持sum、max、min操作类型，即支持取值为HCCL_REDUCE_SUM、HCCL_REDUCE_MAX、HCCL_REDUCE_MIN。HcclReduceOp数据类型的介绍请参考表2。</td></tr><tr><td>repeat</td><td>输入</td><td>一次下发的AllReduce通信任务个数。repeat取值≥1，默认值为1。当repeat&gt;1时，每个AllReduce任务的sendBuf和recvBuf地址由服务端自动算出，计算公式如下： sendBuf[i] = sendBuf + count* sizeof(datatype) * i, i∈[0, repeat) recvBuf[i] = recvBuf + count* sizeof(datatype) * i, i∈[0, repeat) 注意：当设置repeat&gt;1时，须与count参数配合使用，规划通信数据地址。</td></tr></tbody></table><p><strong>图 1</strong> AllReduce三轮切分通信示例<br><img src="`+p+'" alt="" title="AllReduce三轮切分通信示例"></p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>返回该任务的标识handleId，handleId大于等于0。调用失败时，返回 -1。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>调用本接口前确保已调用过<a href="./InitV2.html">InitV2</a>和<a href="./SetCcTilingV2.html">SetCcTilingV2</a>接口。</li><li>若HCCL对象的<a href="./HCCL模板参数.html#table884518212555">config模板参数</a>未指定下发通信任务的核，该接口只能在AIC核或者AIV核两者之一上调用。若HCCL对象的<a href="./HCCL模板参数.html#table884518212555">config模板参数</a>中指定了下发通信任务的核，则该接口可以在AIC核和AIV核上同时调用，接口内部会根据指定的核的类型，只在AIC核、AIV核二者之一下发该通信任务。</li><li>对于Atlas A2 训练系列产品/Atlas A2 推理系列产品，一个通信域内，所有Prepare接口的总调用次数不能超过63。</li><li>对于Atlas A3 训练系列产品/Atlas A3 推理系列产品，一个通信域内，所有Prepare接口和InterHcclGroupSync接口的总调用次数不能超过63。</li><li>对于Ascend 950PR/Ascend 950DT，一个通信域内，所有Prepare接口的总调用次数不能超过63。</li><li>对于Ascend 950PR/Ascend 950DT，通信服务端为CCU时，单次最大通信数据量不能超过256M。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>非多轮切分场景</p><p>如下图所示，4张卡上均有count=300个float16数据，每张卡从xGM内存中获取到本卡数据，各卡的数据进行reduce sum计算后，将结果输出到各卡的yGM。</p><p><strong>图 2</strong> 非多轮切分场景下4卡AllReduce通信</p><p><img src="'+c+`" alt=""></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void all_reduce_custom(GM_ADDR xGM, GM_ADDR yGM, GM_ADDR workspaceGM, GM_ADDR tilingGM) {</span></span>
<span class="line"><span>    auto sendBuf = xGM;  // xGM为AllReduce的输入GM地址</span></span>
<span class="line"><span>    auto recvBuf = yGM;  // yGM为AllReduce的输出GM地址</span></span>
<span class="line"><span>    uint64_t sendCount = 300;  // 每张卡上均有300个float16的数据</span></span>
<span class="line"><span>    HcclReduceOp reduceOp = HcclReduceOp::HCCL_REDUCE_SUM;</span></span>
<span class="line"><span>    REGISTER_TILING_DEFAULT(AllReduceCustomTilingData); //AllReduceCustomTilingData为对应算子头文件定义的结构体</span></span>
<span class="line"><span>    GET_TILING_DATA_WITH_STRUCT(AllReduceCustomTilingData, tilingData, tilingGM);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Hccl hccl;</span></span>
<span class="line"><span>    GM_ADDR contextGM = AscendC::GetHcclContext&lt;0&gt;();  // AscendC自定义算子kernel中，通过此方式获取HCCL context</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    if (AscendC::g_coreType == AIV) {  // 指定AIV核通信   </span></span>
<span class="line"><span>        hccl.InitV2(contextGM, &amp;tilingData);</span></span>
<span class="line"><span>        auto ret = hccl.SetCcTilingV2(offsetof(AllReduceCustomTilingData, mc2CcTiling));</span></span>
<span class="line"><span>        if (ret) {</span></span>
<span class="line"><span>            return;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        HcclHandle handleId1 = hccl.AllReduce&lt;true&gt;(sendBuf, recvBuf, sendCount, HcclDataType::HCCL_DATA_TYPE_FP16, reduceOp);</span></span>
<span class="line"><span>        hccl.Wait(handleId1);    </span></span>
<span class="line"><span>        AscendC::SyncAll&lt;true&gt;();  // 全AIV核同步，防止0核执行过快，提前调用hccl.Finalize()接口，导致其他核Wait卡死   </span></span>
<span class="line"><span>        hccl.Finalize();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>多轮切分场景</p><p>使能多轮切分，等效处理上述非多轮切分示例的通信。如下图所示，每张卡的300个float16数据，被切分为2个首块数据，1个尾块数据。每个首块的数据量tileLen为128个float16数据，尾块的数据量tailLen为44个float16数据。在算子内部实现时，需要对切分后的数据分3轮进行AllReduce通信任务，将等效上述非多轮切分的通信结果。</p><p><strong>图 3</strong> 各卡数据切分示意图<br><img src="`+i+'" alt="" title="各卡数据切分示意图"></p><p>具体实现为，第1轮通信，每个rank上0-0\\1-0\\2-0\\3-0数据块进行AllReduce处理。第2轮通信，每个rank上0-1\\1-1\\2-1\\3-1数据块进行AllReduce处理。第3轮通信，每个rank上0-2\\1-2\\2-2\\3-2数据块进行AllReduce处理，图示及代码示例如下。</p><p><strong>图 4</strong> 4卡AllReduce示意图<br><img src="'+d+`" alt="" title="4卡AllReduce示意图"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void all_reduce_custom(GM_ADDR xGM, GM_ADDR yGM, GM_ADDR workspaceGM, GM_ADDR tilingGM) {</span></span>
<span class="line"><span>    constexpr uint32_t tileNum = 2U;   // 首块数量</span></span>
<span class="line"><span>    constexpr uint64_t tileLen = 128U; // 首块数据个数</span></span>
<span class="line"><span>    constexpr uint32_t tailNum = 1U;   // 尾块数量</span></span>
<span class="line"><span>    constexpr uint64_t tailLen = 44U;  // 尾块数据个数</span></span>
<span class="line"><span>    auto sendBuf = xGM;  // xGM为AllReduce的输入GM地址</span></span>
<span class="line"><span>    auto recvBuf = yGM;  // yGM为AllReduce的输出GM地址</span></span>
<span class="line"><span>    HcclReduceOp reduceOp = HcclReduceOp::HCCL_REDUCE_SUM;</span></span>
<span class="line"><span>    REGISTER_TILING_DEFAULT(AllReduceCustomTilingData); //AllReduceCustomTilingData为对应算子头文件定义的结构体</span></span>
<span class="line"><span>    GET_TILING_DATA_WITH_STRUCT(AllReduceCustomTilingData, tilingData, tilingGM);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Hccl hccl;</span></span>
<span class="line"><span>    GM_ADDR contextGM = AscendC::GetHcclContext&lt;0&gt;();  // AscendC自定义算子kernel中，通过此方式获取HCCL context</span></span>
<span class="line"><span>    if (AscendC::g_coreType == AIV) {  // 指定AIV核通信   </span></span>
<span class="line"><span>        hccl.InitV2(contextGM, &amp;tilingData);</span></span>
<span class="line"><span>        auto ret = hccl.SetCcTilingV2(offsetof(AllReduceCustomTilingData, mc2CcTiling));</span></span>
<span class="line"><span>        if (ret != HCCL_SUCCESS) {</span></span>
<span class="line"><span>            return;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        // 2个首块处理</span></span>
<span class="line"><span>        constexpr uint32_t tileRepeat = tileNum; </span></span>
<span class="line"><span>        // 除了sendBuf和recvBuf入参不同，对2个首块处理的其余参数相同。故使用repeat=2，第2个首块AllReduce任务的sendBuf、recvBuf将由API内部自行更新</span></span>
<span class="line"><span>        HcclHandle handleId1 = hccl.AllReduce&lt;true&gt;(sendBuf, recvBuf, tileLen, HcclDataType::HCCL_DATA_TYPE_FP16, reduceOp, tileRepeat); </span></span>
<span class="line"><span>        // 1个尾块处理</span></span>
<span class="line"><span>        constexpr uint32_t kSizeOfFloat16 = 2U;</span></span>
<span class="line"><span>        sendBuf += tileLen * tileNum * kSizeOfFloat16;</span></span>
<span class="line"><span>        recvBuf += tileLen * tileNum * kSizeOfFloat16;</span></span>
<span class="line"><span>        constexpr uint32_t tailRepeat = tailNum; </span></span>
<span class="line"><span>        HcclHandle handleId2 = hccl.AllReduce&lt;true&gt;(sendBuf, recvBuf, tailLen, HcclDataType::HCCL_DATA_TYPE_FP16, reduceOp, tailRepeat);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        for (uint8_t i=0; i&lt;tileRepeat; i++) {</span></span>
<span class="line"><span>            hccl.Wait(handleId1);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        hccl.Wait(handleId2);  </span></span>
<span class="line"><span>        AscendC::SyncAll&lt;true&gt;();  // 全AIV核同步，防止0核执行过快，提前调用hccl.Finalize()接口，导致其他核Wait卡死   </span></span>
<span class="line"><span>        hccl.Finalize();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,20)])])}const R=n(r,[["render",u]]);export{f as __pageData,R as default};
